    visited = [[False]*cols for _ in range(rows)]
    regions = []

    def flood_fill(r, c, value):
        stack = [(r, c)]
        region = [(r, c)]
        visited[r][c] = True

        while stack:
            cr, cc = stack.pop()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] == value:
